--
-- Name: employee_details_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.employee_details_view AS
 SELECT e.id,
    e.emp_id,
    e.name,
    e.email,
    e.contact_number,
    e.gender,
    e.joining_date,
    e.company,
    e.cost_center,
    m.name AS reports_to_name,
    e.is_technician,
    e.nationality,
    d.name AS designation,
    ad.name AS department,
    et.name AS employee_type,
    r.name AS religion,
    o.name AS origin
   FROM ((((((public.employees e
     LEFT JOIN public.designations d ON ((e.designation_id = d.id)))
     LEFT JOIN public.asset_departments ad ON ((e.department_id = ad.id)))
     LEFT JOIN public.employee_types et ON ((e.employee_type_id = et.id)))
     LEFT JOIN public.religions r ON ((e.religion_id = r.id)))
     LEFT JOIN public.origins o ON ((e.origin_id = o.id)))
     LEFT JOIN public.employees m ON ((m.id = e.reports_to)));


